import assert from "node:assert/strict";
import { writeFileSync, readFileSync } from "node:fs";
import { cpus, release } from "node:os";
import { setTimeout as delay, setImmediate as nextTask } from "node:timers/promises";
import { CodeMode, Tool, Effect } from "./upstream.mjs";
import { CodemodeSandbox } from "file:///D:/RMProjects/Pi/packages/codemode/src/runtime/host.ts";
import { loadQuickJSWasm } from "file:///D:/RMProjects/Pi/packages/codemode/src/wasm.ts";
const payload = "x".repeat(4096);
const rows = Array.from({length:500}, (_,i)=>({id:i,text:"x".repeat(64),active:i%2===0}));
const counters={read:0,rows:0,wait:0};
const host={
  read:()=>{counters.read++;return payload},
  rows:()=>{counters.rows++;return rows},
  wait:async()=>{counters.wait++;await delay(10);return 1}
};
const tools=Object.fromEntries(Object.entries(host).map(([name,fn])=>[name,Tool.make({
  description:name,input:{type:"object"},output:{},
  execute:()=>name==="wait"?Effect.promise(fn):Effect.sync(fn)
})]));
const limits={timeoutMs:60000,maxToolCalls:256,maxOutputBytes:1024*1024};
const options={tools,limits};
const reused=CodeMode.make(options);
const sandbox=new CodemodeSandbox({tools:Object.entries(host).map(([name,execute])=>({name,execute}))});
const t=performance.now(); await loadQuickJSWasm(); const wasmCompileMs=performance.now()-t;
const allCases=[
 {name:"noop",code:"return 1",expected:1,calls:0},
 {name:"one_4KiB_read",code:"return (await tools.read({})).length",expected:4096,calls:1},
 {name:"100_sequential_4KiB_reads",code:"let n=0;for(let i=0;i<100;i++)n+=(await tools.read({})).length;return n",expected:409600,calls:100},
 {name:"100000_integer_loop",code:"let n=0;for(let i=0;i<100000;i++)n+=i;return n",expected:4999950000,calls:0},
 {name:"10000_integer_loop",code:"let n=0;for(let i=0;i<10000;i++)n+=i;return n",expected:49995000,calls:0},
 {name:"500_structured_rows_filter_reduce",code:"const rows=await tools.rows({});return rows.filter(r=>r.active).map(r=>r.id).reduce((a,b)=>a+b,0)",expected:62250,calls:1},
 {name:"8_parallel_10ms_host_calls",code:"return (await Promise.all(Array.from({length:8},()=>tools.wait({})))).reduce((a,b)=>a+b,0)",expected:8,calls:8}
];
const selected=process.argv.find(a=>a.startsWith("--case="))?.slice(7);
const cases=selected?allCases.filter(c=>c.name===selected):allCases.filter(c=>c.name!=="100000_integer_loop");
assert.ok(cases.length);
const variants=["opencode_reused","opencode_make_each","pi_reused_catalog_fresh_worker"];
const samples=Object.fromEntries(cases.map(c=>[c.name,Object.fromEntries(variants.map(v=>[v,[]]))]));
const warmups=2, repetitions=15;
for(const test of cases) for(let i=-warmups;i<repetitions;i++){
  // Rotate ordering to avoid always measuring one runtime first.
  const order=variants.map((_,j)=>variants[(j+(i+warmups)%3)%3]);
  for(const variant of order){
    const begin=performance.now();
    const result=await (variant==="pi_reused_catalog_fresh_worker"?sandbox.execute(test.code):
      Effect.runPromise((variant==="opencode_reused"?reused:CodeMode.make(options)).execute(test.code)));
    const elapsed=performance.now()-begin;
    assert.equal(result.ok,true,JSON.stringify(result));
    assert.equal(result.value,test.expected);
    assert.equal((result.calls??result.toolCalls).length,test.calls);
    if(i>=0)samples[test.name][variant].push(elapsed);
  }
}
const stats=sandbox.stats;
await sandbox.close();
assert.equal(stats.activeExecutions,0);
assert.equal(stats.workersStarted,cases.length*(warmups+repetitions));
assert.equal(stats.workersStopped,stats.workersStarted);
const expectedReplays=variants.length*(warmups+repetitions);
assert.deepEqual(counters,{read:cases.filter(c=>c.name.includes("4KiB")).reduce((n,c)=>n+c.calls,0)*expectedReplays,rows:(cases.some(c=>c.name==="500_structured_rows_filter_reduce")?1:0)*expectedReplays,wait:(cases.some(c=>c.name==="8_parallel_10ms_host_calls")?8:0)*expectedReplays});
const results=Object.fromEntries(Object.entries(samples).map(([name,vs])=>[name,Object.fromEntries(Object.entries(vs).map(([variant,raw])=>{
 const sorted=[...raw].sort((a,b)=>a-b);
 return [variant,{medianMs:sorted[Math.floor(sorted.length/2)],p95Ms:sorted[Math.ceil(sorted.length*0.95)-1],samplesMs:raw}];
}))]));
const evidence={date:new Date().toISOString(),upstreamCommit:"4617210822bdbb31e5749751afbfb4584ccedac8",
 localCommit:"af067d5efe3bc61128a4cda3162d23e908d3ece5",environment:{node:process.version,platform:process.platform,arch:process.arch,os:release(),cpu:cpus()[0].model,effect:"4.0.1",acorn:"8.15.0",quickjsWasi:"3.6.2"},
 method:{warmupsPerCaseVariant:warmups,samplesPerCaseVariant:repetitions,rotatingOrder:true,profiler:false,
 scope:"Library execution only; static imports and host creation excluded; Pi fresh Worker creation and termination included; OpenCode make_each includes CodeMode.make only, not core adapter tree/progress/web/policy.",
 comparableLimits:limits,
 caveats:["Node is a common comparison runtime; OpenCode application uses Bun.","Output limits differ in bytes vs UTF-16 chars; fixtures are ASCII.","No real model, network, disk, policy, UI or complete product/token-cost comparison.","Reused OpenCode runtime is library best case, not core adapter reuse.","Timing does not compare total allocations, peak heap or event-loop responsiveness.","15 samples describe this local run, not a statistically stable production p95."]},
 fixtureBytes:{read:Buffer.byteLength(JSON.stringify(payload)),rows:Buffer.byteLength(JSON.stringify(rows))},
 cases,wasmCompileMs,results,counters,piLifecycle:stats,
 reproduction:{dependencies:{acorn:"8.15.0",effect:"4.0.1"},upstreamSourcePath:"packages/codemode/src",bundle:"esbuild wrapper.ts --bundle --platform=node --format=esm --packages=external --outfile=upstream.mjs",command:"node --experimental-strip-types compare.mjs",wrapper:"export * as CodeMode from \"./packages/codemode/src/codemode.ts\";\nexport * as Tool from \"./packages/codemode/src/tool.ts\";\nexport { Effect } from \"effect\";\n"}
};
writeFileSync(new URL(selected?"./cpu-comparison.json":"./comparison.json",import.meta.url),JSON.stringify(evidence,null,2)+"\n");
for (const [name,vs] of Object.entries(results)) process.stdout.write(JSON.stringify({name,...Object.fromEntries(Object.entries(vs).map(([v,s])=>[v,{median:s.medianMs,p95:s.p95Ms}]))})+"\n");
process.stdout.write(JSON.stringify({wasmCompileMs,counters,piLifecycle:stats})+"\n");
